export const meta = {
  name: 'e2e-exercisability-audit',
  description: 'Determine whether the share itemName lazy-backfill two-party UAT is exercisable in the local full e2e stack',
  phases: [
    { title: 'Investigate' },
    { title: 'Synthesize' },
    { title: 'Verify' },
  ],
}

const REPO = '/Users/myankelev/Code/random/cipher-box'

const CONTEXT = `
REPO ROOT: ${REPO}

FEATURE UNDER QUESTION (just shipped on branch feat/share-itemname-lazy-backfill, PR #505):
- New API endpoint: PATCH /shares/:shareId/item-name (apps/api/src/shares/shares.controller.ts + SharesService.updateShareItemName) — sharer-only; persists client-supplied ECIES ciphertext of the share display name into shares.item_name_encrypted (bytea column). Server is zero-knowledge: never encrypts.
- Web: apps/web/src/services/share.service.ts — backfillSentShareItemNames() re-wraps legacy plaintext itemName for the recipient and persists via the new endpoint; shouldBackfill() decides eligibility (true only when a key-holding owner sees a plaintext-only legacy row, i.e. itemNameEncrypted is absent). It is fired (fire-and-forget) from fetchAllSentShares() on the sent-shares load path.
- decision A2 = lazy CLIENT-side backfill (the server cannot encrypt; only the sharer holds the recipient pubkey to re-wrap). Migration 1749200000000-EncryptShareItemName.ts added the nullable item_name_encrypted column.

THE DEFERRED UAT (the thing we want to know is locally exercisable):
"Two-party: an OWNER who has a LEGACY share (plaintext shares.item_name, NULL item_name_encrypted) loads their sent-shares list, the backfill fires and persists ciphertext; then (a) confirm the share row now carries item_name_encrypted ciphertext AT REST (server never saw plaintext), and (b) the RECIPIENT still sees the correct decrypted display name for the share."

To exercise this locally we need the e2e harness to support: (1) TWO distinct user identities (owner + recipient) in one test; (2) creating/seeding a LEGACY share = plaintext itemName with NULL item_name_encrypted (note: the current create path sends ciphertext, so this needs either a direct DB insert, a legacy-shaped DTO that omits itemNameEncrypted, or a fixture); (3) asserting on Postgres row state (item_name_encrypted non-null + that it is ciphertext, not plaintext) and/or recipient-side decrypted display.
`

const FINDINGS_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    angle: { type: 'string' },
    capable: { type: 'string', enum: ['yes', 'partial', 'no', 'unknown'] },
    summary: { type: 'string', description: 'Direct answer to this angle in 2-4 sentences' },
    evidence: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          file: { type: 'string', description: 'path:line or path' },
          note: { type: 'string' },
        },
        required: ['file', 'note'],
      },
    },
    blockers: { type: 'array', items: { type: 'string' }, description: 'Concrete gaps that would block exercising the UAT via this angle' },
  },
  required: ['angle', 'capable', 'summary', 'evidence', 'blockers'],
}

const ANGLES = [
  {
    key: 'stack-and-launch',
    prompt: `ANGLE: web-e2e local stack & how it is launched.
Find where the web e2e tests live (e.g. tests/web-e2e/), the Playwright config, and HOW the full local stack is stood up for them (docker compose? a script like scripts/*.sh? what services: API/Postgres/IPFS-Kubo/TEE-simulator?). Determine whether a developer can run this stack + specs LOCALLY (not just in CI web-e2e.yml). Look at package.json scripts, playwright.config, README/DEVELOPMENT docs, and any compose files. Report exactly how one launches it locally and what backing services come up (especially: is there a real Postgres a test could query?).`,
  },
  {
    key: 'two-party-identities',
    prompt: `ANGLE: multi-user / two-party support in the e2e harness.
Find existing e2e specs that involve TWO different users (a sharer and a recipient) — sharing flows, invites, shared-folder sync, cross-client sync. Look in tests/web-e2e/tests/ and any desktop cross-client-sync e2e. Determine how a spec establishes two distinct authenticated identities (dev-key login? --dev-key? multiple browser contexts? seeded users?). Quote the mechanism. If two-party scenarios already exist and pass, that strongly implies the owner+recipient setup is reusable. Name the closest existing spec to model on.`,
  },
  {
    key: 'db-assertion',
    prompt: `ANGLE: can e2e assert on Postgres row state (ciphertext-at-rest)?
Determine whether the e2e harness can read/assert the database directly — e.g. a pg client, a TypeORM connection in test setup, a helper that queries shares rows, or an API/debug endpoint that exposes raw row state. Search tests/web-e2e and apps/api for any test DB access. The UAT needs to assert shares.item_name_encrypted is non-null AND is ciphertext (not the UTF-8 plaintext name). If no direct DB access exists, identify the next-best signal (e.g. the GET /shares/sent response returns itemNameEncrypted as hex — apps/api/src/shares/shares.controller.ts maps it; a test could assert the API now returns ciphertext for that row). Report what's possible.`,
  },
  {
    key: 'legacy-row-and-trigger',
    prompt: `ANGLE: creating a LEGACY plaintext-only share + triggering the backfill.
Two sub-questions. (1) How can a test create a share row with plaintext itemName and NULL item_name_encrypted? Check create-share.dto.ts and shares.service.ts: is itemNameEncrypted OPTIONAL on create (so a test can POST a legacy-shaped share that omits it)? Or would a direct DB insert / SQL be needed? (2) How is the backfill actually triggered in the running web app — confirm the call path fetchAllSentShares() -> backfillSentShareItemNames() in apps/web/src/services/share.service.ts, what UI action loads sent shares, and that shouldBackfill() returns true for the legacy row (owner is key-holder). Report whether a local e2e could deterministically drive owner-login -> open sent-shares -> backfill fires -> assert.`,
  },
]

phase('Investigate')
log('Fanning out 4 read-only investigators across the e2e harness...')
const findings = await parallel(
  ANGLES.map((a) => () =>
    agent(`${CONTEXT}\n\n${a.prompt}\n\nBe concrete and cite real files with line numbers where possible. If something does not exist, say so explicitly (capable: "no" with the blocker).`, {
      label: `investigate:${a.key}`,
      phase: 'Investigate',
      agentType: 'Explore',
      schema: FINDINGS_SCHEMA,
    })
  )
)

const clean = findings.filter(Boolean)

phase('Synthesize')
const VERDICT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    exercisable: { type: 'string', enum: ['fully', 'partially', 'no'] },
    rationale: { type: 'string' },
    test_plan: { type: 'array', items: { type: 'string' }, description: 'Ordered concrete steps to implement the UAT as a local e2e spec' },
    new_harness_needed: { type: 'array', items: { type: 'string' }, description: 'Any harness capability that must be ADDED (vs reused)' },
    residual_human_only: { type: 'array', items: { type: 'string' }, description: 'Parts that genuinely still require a human / cannot be automated locally' },
    confidence: { type: 'number' },
  },
  required: ['exercisable', 'rationale', 'test_plan', 'new_harness_needed', 'residual_human_only', 'confidence'],
}
const synthesis = await agent(
  `${CONTEXT}\n\nFour investigators returned these structured findings:\n\n${JSON.stringify(clean, null, 2)}\n\nSynthesize a single verdict: is the deferred two-party itemName-backfill UAT exercisable in the LOCAL full e2e environment? Decide "fully" (all three needs — two identities, legacy-row creation, at-rest/recipient assertion — are reusable or trivially addable), "partially" (some reusable, some needs new harness work or a weaker proxy assertion), or "no" (a hard blocker). Give a concrete ordered test_plan to implement it as a local e2e spec, list any new_harness_needed, and be honest about residual_human_only. Ground every claim in the findings' evidence.`,
  { label: 'synthesize-verdict', phase: 'Synthesize', schema: VERDICT_SCHEMA }
)

phase('Verify')
const VERIFY_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    holds: { type: 'boolean', description: 'Does the synthesis verdict hold up against the actual repo?' },
    corrections: { type: 'array', items: { type: 'string' } },
    adjusted_exercisable: { type: 'string', enum: ['fully', 'partially', 'no'] },
    key_risks: { type: 'array', items: { type: 'string' } },
    notes: { type: 'string' },
  },
  required: ['holds', 'corrections', 'adjusted_exercisable', 'key_risks', 'notes'],
}
const verdict = await agent(
  `${CONTEXT}\n\nA synthesis produced this verdict:\n\n${JSON.stringify(synthesis, null, 2)}\n\nADVERSARIALLY verify it against the ACTUAL repo. Open the files the test_plan relies on and confirm: (a) the e2e harness really stands up a local Postgres a test can reach (or that the API-response proxy assertion is real); (b) two-party identity setup truly exists and is reusable (name the spec and the mechanism); (c) a legacy plaintext-only share can really be created (is itemNameEncrypted actually optional on the create DTO/service? — read create-share.dto.ts and shares.service.ts); (d) the backfill trigger path is real and deterministic. Default to skepticism: if a claimed capability is not actually present, downgrade. Return whether it holds, concrete corrections, your adjusted exercisable rating, and the key risks of implementing the spec.`,
  { label: 'verify-verdict', phase: 'Verify', schema: VERIFY_SCHEMA }
)

return { synthesis, verdict, findings: clean }

