191	                    folder_entry: Some(FolderEntry {
192	                        id: "folder-id".to_string(),
193	                        name: "old-folder".to_string(),
194	                        ipns_name: "k51folder".to_string(),
195	                        folder_key_encrypted: "aabb".to_string(),
