197	                        created_at: 1000,
198	                        modified_at: 2000,
199	                    }),
200	                },
201	            ],
202	        };
203	
204	        let encrypted = encrypt_bin_metadata(&metadata, &pk).unwrap();
205	        let decrypted = decrypt_bin_metadata(&encrypted, &sk).unwrap();
206	
207	        assert_eq!(decrypted.version, "v1");
208	        assert_eq!(decrypted.sequence_number, 5);
209	        assert_eq!(decrypted.entries.len(), 2);
210	        assert_eq!(decrypted.entries[0].id, "entry-1");
211	        assert_eq!(decrypted.entries[0].name, "deleted-photo.jpg");
212	        assert_eq!(decrypted.entries[1].id, "entry-2");
213	        assert!(decrypted.entries[1].folder_entry.is_some());
214	    }
